// Hand-crafted code samples for the flagship endpoints.
//
// Per docs/SCALAR_DOCS_ENHANCEMENT_PLAN.md §10. Each entry is keyed by
// (method, path). At spec-render time, applyCodeSamples() walks the
// generated OpenAPI doc and attaches `x-codeSamples` to the matching
// operation. operationIds are auto-generated by @hono/zod-openapi, so
// keying by (method, path) is the durable contract.
//
// Languages: shell (curl), js (TS via fetch), python (requests).
// Each sample uses two placeholder strings the user replaces:
//   {{TENANT_API_KEY}}  → their own X-Textral-Api-Key
//   {{WORKER_URL}}      → e.g. https://textral-api-dev.<sub>.workers.dev

export interface CodeSample {
  lang: 'shell' | 'js' | 'python';
  label: string;
  source: string;
}

export interface SampleKey {
  method: 'get' | 'post' | 'put' | 'delete' | 'patch';
  path: string;
}

interface SampleEntry {
  key: SampleKey;
  samples: CodeSample[];
}

const KEY = '{{TENANT_API_KEY}}';
const URL_ = '{{WORKER_URL}}';

