// ─── 5. Upload bytes (presign + PUT, two-step) ────────────────────
const UPLOAD_BYTES: SampleEntry = {
  key: { method: 'post', path: '/v1/documents/{id}/uploads' },
  samples: [
    {
      lang: 'shell',
      label: 'curl',
      source: `# Step 1: get the upload URL.
UPLOAD_JSON=$(curl -s -X POST "${URL_}/v1/documents/$DOC_ID/uploads" \\
  -H "X-Textral-Api-Key: ${KEY}" \\
  -H 'content-type: application/json' \\
  -d '{
    "content_type": "text/markdown",
    "size_bytes": '"$(stat -c%s ./mydoc.md)"'
  }')

UPLOAD_URL=$(echo "$UPLOAD_JSON" | jq -r .url)
UPLOAD_ID=$(echo "$UPLOAD_JSON" | jq -r .upload_id)

# Step 2: PUT the bytes (URL points back at the Worker — proxied).
curl -X PUT "$UPLOAD_URL" \\
  -H 'content-type: text/markdown' \\
  -H "X-Textral-Api-Key: ${KEY}" \\
  --data-binary @./mydoc.md

# Step 3: see the finalize sample.`,
    },
    {
      lang: 'js',
      label: 'TypeScript (fetch)',
      source: `const stat = await Deno.stat('./mydoc.md');  // or fs.stat in Node
const upload = await fetch(\`\${WORKER_URL}/v1/documents/\${docId}/uploads\`, {
  method: 'POST',
  headers: { 'X-Textral-Api-Key': API_KEY, 'content-type': 'application/json' },
  body: JSON.stringify({ content_type: 'text/markdown', size_bytes: stat.size }),
}).then((r) => r.json());

await fetch(upload.url, {
  method: 'PUT',
  headers: { 'X-Textral-Api-Key': API_KEY, 'content-type': 'text/markdown' },
  body: await Deno.readFile('./mydoc.md'),
});
// Then call .../finalize.`,
    },
    {
      lang: 'python',
      label: 'Python (requests)',
      source: `import os
size = os.path.getsize("./mydoc.md")
upload = requests.post(
    f"{WORKER_URL}/v1/documents/{doc_id}/uploads",
    headers={"X-Textral-Api-Key": API_KEY, "content-type": "application/json"},
    json={"content_type": "text/markdown", "size_bytes": size},
).json()

with open("./mydoc.md", "rb") as f:
    requests.put(
        upload["url"],
        headers={"X-Textral-Api-Key": API_KEY, "content-type": "text/markdown"},
        data=f,
    )

# Then call .../finalize.`,
    },
  ],
};

