// ─── 8. Poll an ingestion job ─────────────────────────────────────
const POLL_JOB: SampleEntry = {
  key: { method: 'get', path: '/v1/ingestion-jobs/{id}' },
  samples: [
    {
      lang: 'shell',
      label: 'curl',
      source: `# Polling loop (simplified).
while true; do
  STATUS=$(curl -s "${URL_}/v1/ingestion-jobs/$JOB_ID" \\
    -H "X-Textral-Api-Key: ${KEY}" | jq -r .status)
  echo "status: $STATUS"
  case "$STATUS" in
    completed|failed) break ;;
    *) sleep 5 ;;
  esac
done`,
    },
    {
      lang: 'js',
      label: 'TypeScript (fetch)',
      source: `async function pollJob(jobId: string, timeoutMs = 240_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const r = await fetch(\`\${WORKER_URL}/v1/ingestion-jobs/\${jobId}\`, {
      headers: { 'X-Textral-Api-Key': API_KEY },
    }).then((r) => r.json());
    if (r.status === 'completed' || r.status === 'failed') return r;
    await new Promise((rs) => setTimeout(rs, 5_000));
  }
  throw new Error('job poll timed out');
}`,
    },
    {
      lang: 'python',
      label: 'Python (requests)',
      source: `import time
def poll_job(job_id, timeout_s=240):
    start = time.time()
    while time.time() - start < timeout_s:
        r = requests.get(
            f"{WORKER_URL}/v1/ingestion-jobs/{job_id}",
            headers={"X-Textral-Api-Key": API_KEY},
        ).json()
        if r["status"] in ("completed", "failed"):
            return r
        time.sleep(5)
    raise TimeoutError("job poll timed out")`,
    },
  ],
};

