// ─── 10. Streaming query (SSE) ────────────────────────────────────
// Same path as #9 but with ?stream=sse — Scalar shows it as a
// separate operation only if we register it as one. For now we
// document it inside the sync query's description and as a
// snippet here keyed on the same path; the renderer dedupes by
// (path, method) so we attach this as an *additional* sample on
// the sync query.
const STREAMING_QUERY_SAMPLE: CodeSample[] = [
  {
    lang: 'shell',
    label: 'curl (?stream=sse)',
    source: `curl -N -X POST "${URL_}/v1/query?stream=sse" \\
  -H "X-Textral-Api-Key: ${KEY}" \\
  -H 'accept: text/event-stream' \\
  -H 'content-type: application/json' \\
  -d '{
    "namespace": "my-docs",
    "query": "What does the doc say about X?",
    "embedding": { "provider": "openai", "model": "text-embedding-3-large", "dimensions": 1536, "provider_key_ref": "default" },
    "inference": { "provider": "openai", "model": "gpt-4o-mini", "provider_key_ref": "default" },
    "chunking": { "profile": "generic" },
    "retrieval": { "strategy": "hybrid_rrf", "top_k_dense": 5, "top_k_sparse": 5 }
  }'

# Two event types: token (per delta) and done (single final event).`,
  },
  {
    lang: 'js',
    label: 'TypeScript (fetch + SSE)',
    source: `const res = await fetch(\`\${WORKER_URL}/v1/query?stream=sse\`, {
  method: 'POST',
  headers: {
    'X-Textral-Api-Key': API_KEY,
    'accept': 'text/event-stream',
    'content-type': 'application/json',
  },
  body: JSON.stringify({ /* same as sync query body */ }),
});
const reader = res.body!.getReader();
const dec = new TextDecoder();
let buf = '';
while (true) {
  const { value, done } = await reader.read();
  if (done) break;
  buf += dec.decode(value, { stream: true });
  let idx;
  while ((idx = buf.indexOf('\\n\\n')) >= 0) {
    const frame = buf.slice(0, idx); buf = buf.slice(idx + 2);
    // frame: "event: token\\ndata: {...}"  or  "event: done\\ndata: {...}"
    console.log(frame);
  }
}`,
  },
  {
    lang: 'python',
    label: 'Python (requests + SSE)',
    source: `import json, requests
with requests.post(
    f"{WORKER_URL}/v1/query?stream=sse",
    headers={
        "X-Textral-Api-Key": API_KEY,
        "accept": "text/event-stream",
        "content-type": "application/json",
    },
    json={ "namespace": "my-docs", "query": "...", "embedding": {...}, "inference": {...},
           "chunking": {"profile": "generic"},
           "retrieval": {"strategy": "hybrid_rrf", "top_k_dense": 5, "top_k_sparse": 5} },
    stream=True,
) as r:
    buf = ""
    for chunk in r.iter_content(chunk_size=None, decode_unicode=True):
        buf += chunk
        while "\\n\\n" in buf:
            frame, buf = buf.split("\\n\\n", 1)
            event = next((l[7:] for l in frame.split("\\n") if l.startswith("event: ")), "")
            data = next((l[6:] for l in frame.split("\\n") if l.startswith("data: ")), "")
            if event == "token":
                print(json.loads(data)["text"], end="", flush=True)
            elif event == "done":
                done = json.loads(data)
                print(f"\\n[done — degradation={done['degradation_level']}]")`,
  },
];

